   431	// ---------------------------------------------------------------------------
   432	// Test: tasks that can never succeed exhaust their retry budget (MAX_OOM_RETRIES=10)
   433	// and cause the query to fail, while small tasks that fit in memory still complete.
   434	//
   435	// Memory layout:
   436	//   GPU capacity  = 1100 MB
   437	//   small_task    =    1 MB allocation  → always succeeds
   438	//   xl_task       = 2048 MB allocation  → always OOMs (exceeds capacity)
   439	//
   440	// We dispatch 5 small tasks + 3 XL tasks = 8 total.
   441	// The XL tasks will be rescheduled up to 10 times each before the executor
   442	// reports a max-retry error on the completion handler.
   443	// The 5 small tasks should all complete regardless.
   444	// After the error, drain_and_wait() should empty the task queue.
   445	// ---------------------------------------------------------------------------
   446	TEST_CASE("GPU pipeline executor fails after max OOM retries",
   447	          "[gpu_pipeline_executor][oom][max_retries]")
   448	{
   449	  oom_test_fixture f;
   450	  if (!f.setup(3, "oom-retry")) {
   451	    WARN("Skipping max-retry OOM test — no GPU available.");
   452	    return;
   453	  }
   454	
   455	  auto global_state = std::make_shared<oom_test_global_state>();
   456	
   457	  const int num_small = 5;
   458	  const int num_xl    = 3;
   459	  const int num_tasks = num_small + num_xl;
   460	  std::atomic<int> dispatched{0};
   461	
   462	  f.executor->start();
   463	
   464	  // Post-v1.0 push-model (commit 90dc104): schedule tasks directly instead of
   465	  // waiting on request_channel.get(). First num_small tasks become small_tasks,
   466	  // the rest xl_tasks.
   467	  std::thread request_handler([&]() {
   468	    while (dispatched.load(std::memory_order_relaxed) < num_tasks) {
   469	      auto id          = static_cast<uint64_t>(dispatched.load(std::memory_order_relaxed));
   470	      auto local_state = std::make_unique<sirius::pipeline::gpu_pipeline_task_local_state>(
   471	        std::make_unique<sirius::op::pipelineable_operator_data>(
   472	          std::vector<std::shared_ptr<cucascade::data_batch>>{}));
   473	
   474	      std::unique_ptr<sirius::parallel::itask> task;
   475	      if (id < static_cast<uint64_t>(num_small)) {
   476	        task = std::make_unique<small_task>(id, std::move(local_state), global_state);
   477	      } else {
   478	        task = std::make_unique<xl_task>(id, std::move(local_state), global_state);
   479	      }
   480	      f.executor->schedule(std::move(task));
   481	      dispatched.fetch_add(1, std::memory_order_relaxed);
   482	    }
   483	  });
   484	
   485	  //--------------------------------------------------------------------------
   486	  // Wait for the completion handler to report an error (max retries exceeded)
   487	  //--------------------------------------------------------------------------
   488	  auto start_time = std::chrono::steady_clock::now();
   489	  auto timeout    = std::chrono::seconds(60);
   490	  while (!f.completion.has_error()) {
   491	    std::this_thread::sleep_for(std::chrono::milliseconds(50));
   492	    if (std::chrono::steady_clock::now() - start_time > timeout) {
   493	      f.executor->stop();
   494	      f.request_channel.close();
   495	      request_handler.join();
   496	      FAIL("Timed out waiting for max-retry OOM error. "
   497	           << "Completed: " << global_state->completed_count.load()
   498	           << ", OOM count: " << global_state->oom_count.load());
   499	    }
   500	  }
   501	
   502	  //--------------------------------------------------------------------------
   503	  // Drain remaining tasks and shut down
   504	  //--------------------------------------------------------------------------
   505	  f.executor->drain_and_wait();
   506	  f.request_channel.close();
   507	  request_handler.join();
   508	  f.executor->stop();
   509	
   510	  //--------------------------------------------------------------------------
   511	  // Validate results
   512	  //--------------------------------------------------------------------------
   513	  if (global_state->error_count.load(std::memory_order_relaxed) > 0) {
   514	    std::lock_guard<std::mutex> lock(global_state->error_mutex);
   515	    for (const auto& error : global_state->errors) {
   516	      INFO(error);
   517	    }
   518	  }
   519	
   520	  // All small tasks should have completed successfully.
   521	  REQUIRE(global_state->error_count.load(std::memory_order_relaxed) == 0);
   522	  REQUIRE(global_state->completed_count.load(std::memory_order_relaxed) == num_small);
   523	
   524	  // The completion handler should be in an error state from exceeding max retries.
   525	  REQUIRE(f.completion.has_error());
   526	
   527	  // XL tasks should have OOM'd many times (at least 10 for the one that hit the limit).
   528	  REQUIRE(global_state->oom_count.load(std::memory_order_relaxed) >= 10);
   529	
   530	  // After drain_and_wait(), the task queue should be empty.
   531	  REQUIRE(f.executor->is_task_queue_empty());
   532	
   533	  INFO("Max-retry OOM test passed: " << global_state->oom_count.load() << " OOM events, "
   534	                                     << global_state->completed_count.load()
   535	                                     << " small tasks completed, error correctly reported");
   536	}
===== README.md
# Pipeline Executor Tests

This directory contains unit tests for the pipeline executor and GPU pipeline executor components.

## Test Coverage

### `test_task_scheduler.cpp`

This test file validates the functionality of the task scheduling framework without executing actual GPU operations. The tests focus on:

#### Thread Pool Functionality
- **Start/Stop Lifecycle**: Verifies that executors can be started and stopped gracefully without hanging or crashing
- **Multiple Cycles**: Ensures executors can be restarted after stopping and continue to work correctly
- **Worker Thread Management**: Tests that worker threads are properly created and terminated

#### Queue Functionality
- **Task Queue Operations**: Tests task submission and retrieval from the pipeline queue
- **Request Queue Operations**: Tests task request submission and retrieval
- **Empty Queue Handling**: Verifies graceful shutdown when no tasks are in the queue
- **Rapid Submission**: Tests queue behavior under heavy load with many tasks submitted quickly
- **Synchronization**: Validates proper coordination between task queue and request queue

#### Task Scheduler & GPU Pipeline Executor Interaction
- **Task Dispatching**: Tests that the task_scheduler correctly dispatches tasks to GPU executors
- **Multi-GPU Support**: Verifies tasks can be routed to different GPU executors based on device_id
- **Task-Request Pairing**: Ensures tasks and their corresponding requests are properly synchronized
- **Task Execution**: Validates that scheduled tasks are actually executed by the GPU executors

## Mock Components

The tests use mock implementations to avoid dependencies on actual GPU hardware:

- **`mock_gpu_pipeline_task`**: Simulates a GPU pipeline task by incrementing counters and recording execution
- **`mock_gpu_pipeline_task_global_state`**: Tracks execution metrics across all tasks
- **`mock_gpu_pipeline_task_local_state`**: Stores per-task information like task ID and expected GPU ID

## Running the Tests

These tests are integrated into the main test suite and will run as part of the standard test execution:

```bash
# Build and run all tests
make test

# Or run just the task scheduler tests using catch2 tags
./build/release/test/unittest "[task_scheduler]"
./build/release/test/unittest "[gpu_pipeline_executor]"
```

## Test Timeouts

All tests include timeout protection (5-15 seconds depending on test complexity) to prevent infinite hangs if something goes wrong with the threading or queuing logic.

