101	
102	  // Memory space matches — return the read-only accessor directly
103	  if (read_accessor.get_memory_space() != nullptr &&
104	      read_accessor.get_memory_space()->get_id() == target_space->get_id()) {
105	    return std::move(read_accessor);
106	  }
107	
108	  // Memory space mismatch — clone or move depending on where the data lives.
109	  auto& registry = sirius::converter_registry::get();
110	
111	  switch (target_space->get_tier()) {
112	    case cucascade::memory::Tier::GPU: {
113	      if (read_accessor.get_current_tier() == cucascade::memory::Tier::GPU) {
114	        // Cross-GPU: clone into the target space under the shared lock. The source is never
115	        // exclusively locked or mutated. clone_to routes through convert_gpu_to_gpu, which waits
