226	{
227	  auto self = shared_from_this();
228	  // Drain reader events before taking the exclusive lock: a registered read may only retire
229	  // after CPU work that itself needs a lock on this batch, so waiting while holding the lock
230	  // could deadlock. Readers may record again between the drain and the acquisition, so re-check
231	  // under the lock and retry.
232	  while (true) {
233	    synchronize_reader_events();
234	    std::unique_lock<std::shared_mutex> lock(_rw_mutex);
235	    if (reader_events_complete()) { return mutable_data_batch(std::move(self), std::move(lock)); }
236	  }
237	}
