113	/// Sum of every pipeline's scheduling counters (+1 per finished pipeline): changes whenever any
114	/// task is created or completes or a pipeline finishes, so a stalled query — zero tasks anywhere
115	/// and nothing finishing — has a constant fingerprint. Counters are atomics; no lock needed.
116	std::uint64_t query_progress_fingerprint(duckdb::SiriusContext& sirius_ctx)
117	{
118	  std::uint64_t fingerprint = 0;
119	  if (auto query = sirius_ctx.get_query()) {
120	    for (const auto& pipeline : query->get_pipelines()) {
121	      if (!pipeline) { continue; }
122	      fingerprint += pipeline->get_tasks_created() + pipeline->get_tasks_completed();
123	      fingerprint += pipeline->is_pipeline_finished() ? 1 : 0;
124	    }
125	  }
126	  return fingerprint;
127	}
