129	/// Wait for the query future. With SIRIUS_QUERY_WATCHDOG_SECS set (> 0) this polls instead of
130	/// blocking: when no pipeline makes scheduling progress for that many seconds, the query is
131	/// failed loudly through the scheduler's completion handler (first-call-wins; no stop or drain
132	/// here — draining belongs to execute()'s catch) and the failed future is rethrown to the
133	/// caller. Off by default: an in-flight long-running kernel makes no counter progress, so only
134	/// opt in where per-operator runtimes are known to sit far below the threshold (the CN cluster
135	/// env sets 60s).
136	void wait_for_query_future(std::future<void>& future, duckdb::SiriusContext& sirius_ctx)
137	{
138	  std::uint64_t watchdog_secs = 0;
139	  if (const char* env = std::getenv("SIRIUS_QUERY_WATCHDOG_SECS"); env != nullptr && *env != '\0') {
140	    char* end         = nullptr;
141	    auto const parsed = std::strtoull(env, &end, 10);
142	    if (end == env || *end != '\0') {
143	      throw invalid_input_exception(
144	        "SIRIUS_QUERY_WATCHDOG_SECS must be a non-negative integer, "
145	        "got: '" +
146	        std::string(env) + "'");
147	    }
148	    watchdog_secs = parsed;
149	  }
150	  if (watchdog_secs == 0) {
151	    future.get();
152	    return;
153	  }
154	
155	  auto last_fingerprint = query_progress_fingerprint(sirius_ctx);
156	  auto last_progress    = std::chrono::steady_clock::now();
157	  while (future.wait_for(std::chrono::milliseconds(250)) != std::future_status::ready) {
158	    auto const fingerprint = query_progress_fingerprint(sirius_ctx);
159	    auto const now         = std::chrono::steady_clock::now();
160	    if (fingerprint != last_fingerprint) {
161	      last_fingerprint = fingerprint;
162	      last_progress    = now;
163	      continue;
164	    }
165	    if (now - last_progress >= std::chrono::seconds(watchdog_secs)) {
166	      // Resolves the future with an error unless the query completed concurrently
167	      // (first-call-wins); the next wait_for observes it and the loop exits into get().
168	      sirius_ctx.get_task_scheduler().fail_stalled_query(watchdog_secs);
169	    }
170	  }

